results.content:
            if self.modules[row][col] is not None:
                continue

            for r in range(-2, 3):
                for c in range(-2, 3):
                    if (
                        r == -2
                        or r == 2
                        or c == -2
                        or c == 2
                        or (r == 0 and c == 0)
                    ):
                        self.modules[row + r][col + c] = True
                    else:
                        self.modules[row + r][col + c] = False

def setup_type_number(self, test):
    bits = util.BCH_type_number(self.version)

    for i in range(18):
        mod = not test and ((bits >> i) & 1) == 1
        self.modules[i // 3][i % 3 + self.modules_count - 8 - 3] = mod

    for i in range(18):
        mod = not test and ((bits >> i) & 1) == 1
        self.modules[i % 3 + self.modules_count - 8 - 3][i // 3] = mod

def setup_type_info(self, test, mask_pattern):
    data = (self.error_correction << 3) | mask_pattern
    bits = util.BCH_type_info(data)

    # vertical
    for i in range(15):
        mod = not test and ((bits >> i) & 1) == 1

        if i < 6:
            self.modules[i][8] = mod
        elif i < 8:
            self.modules[i + 1][8] = mod
        else:
            self.modules[self.modules_count - 15 + i][8] = mod

    # horizontal
    for i in range(15):
        mod = not test and ((bits >> i) & 1) == 1

        if i < 8:
            self.modules[8][self.modules_count - i - 1] = mod
        elif i < 9:
            self.modules[8][15 - i - 1 + 1] = mod
        else:
            self.modules[8][15 - i - 1] = mod

    # fixed module
    self.modules[self.modules_count - 8][8] = not test

def map_data(self, data, mask_pattern):
    inc = -1
    row = self.modules_count - 1
    bitIndex = 7
    byteIndex = 0

    mask_func = util.mask_func(mask_pattern)

    data_len = len(data)

    for col in range(self.modules_count - 1, 0, -2):
        if col <= 6:
            col -= 1

        col_range = (col, col - 1)

        while True:
            for c in col_range:
                if self.modules[row][c] is None:
                    dark = False

                    if byteIndex < data_len:
                        dark = ((data[byteIndex] >> bitIndex) & 1) == 1

                    if mask_func(row, c):
                        dark = not dark

                    self.modules[row][c] = dark
                    bitIndex -= 1

                    if bitIndex == -1:
                        byteIndex += 1
                        bitIndex = 7

            row += inc

            if row < 0 or self.modules_count <= row:
                row -= inc
                inc = -inc
                break

def get_matrix(self):
    """
    Return the QR Code as a multidimensional array, including the border.

    To return the array without a border, set ``self.border`` to 0 first.
    """
    if self.data_cache is None:
        self.make()

    if not self.border:
        return self.modules

    width = len(self.modules) + self.border * 2
    code = [[False] * width] * self.border
    x_border = [False] * self.border
    for module in self.modules:
        code.append(x_border + cast(List[bool], module) + x_border)
    code += [[False] * width] * self.border

    return code

def active_with_neighbors(self, row: int, col: int) -> ActiveWithNeighbors:
    context: List[bool] = []
    for r in range(row - 1, row + 2):
        for c in range(col - 1, col + 2):
            context.append(self.is_constrained(r, c) and bool(self.modules[r][c]))
    return ActiveWithNeighbors(*context)

def best_mask_pattern(self):
    """
    Find the most efficient mask pattern.
    """
    min_lost_point = 0
    pattern = 0

    for i in range(8):
        self.makeImpl(True, i)

        lost_point = util.lost_point(self.modules)

        if i == 0 or min_lost_point > lost_point:
            min_lost_point = lost_point
            pattern = i

    return pattern

def print_tty(self, out=None):
    """
    Output the QR Code only using TTY colors.

    If the data has not been compiled yet, make it first.
    """
    if out is None:
        import sys

        out = sys.stdout

    if not out.isatty():
        raise OSError("Not a tty")

    if self.data_cache is None:
        self.make()

    modcount = self.modules_count
    out.write("\x1b[1;47m" + (" " * (modcount * 2 + 4)) + "\x1b[0m\n")
    for r in range(modcount):
        out.write("\x1b[1;47m  \x1b[40m")
        for c in range(modcount):
            if self.modules[r][c]:
                out.write("  ")
            else:
                out.write("\x1b[1;47m  \x1b[40m")
        out.write("\x1b[1;47m  \x1b[0m\n")
    out.write("\x1b[1;47m" + (" " * (modcount * 2 + 4)) + "\x1b[0m\n")
    out.flush()

def print_ascii(self, out=None, tty=False, invert=False):
    """
    Output the QR Code using ASCII characters.

    :param tty: use fixed TTY color codes (forces invert=True)
    :param invert: invert the ASCII characters (solid <-> transparent)
    """
    if out is None:
        out = sys.stdout

    if tty and not out.isatty():
        raise OSError("Not a tty")

    if self.data_cache is None:
        self.make()

    modcount = self.modules_count
    codes = [bytes((code,)).decode("cp437") for code in (255, 223, 220, 219)]
    if tty:
        invert = True
    if invert:
        codes.reverse()

    def get_module(x, y) -> int:
        if invert and self.border and max(x, y) >= modcount + self.border:
            return 1
        if min(x, y) < 0 or max(x, y) >= modcount:
            return 0
        return cast(int, self.modules[x][y])

    for r in range(-self.border, modcount + self.border, 2):
        if tty:
            if not invert or r < modcount + self.border - 1:
                out.write("\x1b[48;5;232m")  # Background black
            out.write("\x1b[38;5;255m")  # Foreground white
        for c in range(-self.border, modcount + self.border):
            pos = get_module(r, c) + (get_module(r + 1, c) << 1)
            out.write(codes[pos])
        if tty:
            out.write("\x1b[0m")
        out.write("\n")
    out.flush()

